<?php use App\Actions\CancelOrderAction; use App\Actions\CreateOrderAction; use App\Models\Category; use App\Models\FoodItem; use App\Models\Stall; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; uses(Tests\TestCase::class, RefreshDatabase::class); test('CreateOrderAction calculates total amount accurately', function () { $student = User::factory()->create(['role' => 'student']); $stall = Stall::factory()->create(); $cat = Category::factory()->create(); $food = FoodItem::factory()->create(['stall_id' => $stall->id, 'category_id' => $cat->id, 'price' => 7.50, 'availability' => true]); $order = (new CreateOrderAction())->execute($student, $stall->id, '12:30 PM', [['food_item_id' => $food->id, 'quantity' => 3]]); expect((float) $order->total_amount)->toBe(22.50)->and($order->status)->toBe('Pending'); }); test('CancelOrderAction throws DomainException if order is not Pending', function () { $student = User::factory()->create(['role' => 'student']); $stall = Stall::factory()->create(); $cat = Category::factory()->create(); $food = FoodItem::factory()->create(['stall_id' => $stall->id, 'category_id' => $cat->id, 'price' => 5.00]); $order = (new CreateOrderAction())->execute($student, $stall->id, '12:30 PM', [['food_item_id' => $food->id, 'quantity' => 1]]); $order->update(['status' => 'Preparing']); expect(fn () => (new CancelOrderAction())->execute($order))->toThrow(DomainException::class); });